-- Fortuna / kindmops. Self-loading encrypted release; embedded keys are extractable.
local PACKAGE=table.freeze({
    Key='/G4FYFD42FfbBnOvzvI/z1HApdODgCJywGgaKWoDVSE=', -- string: base64 AES-256 key for this release
    IV='PZ+3xN8HxSBXGKKj4qBhwQ==', -- string: base64 CBC initialization vector
    MacKey='3Ah1tq0bQ5H9RVC81CA1mIvWpMheN73EsxJs12mrmPA=', -- string: base64 independent HMAC-SHA256 key
    Tag='13234cb2797b84c1f20b7d0b04fd9a56f6044c016313147b21d7151174265fe1', -- string: authenticated envelope digest
    SourceSHA256='cd4e2017a7f515c88375cd7dc03bcd530016a5fa9e92fa8c89437562cc8d21bc', -- string: exact verified plaintext identity
    SourceBytes=12348529, -- number: expected plaintext byte count
    Cipher='', -- string: base64 AES-256-CBC/PKCS7 payload
})
assert(type(crypt)=='table'and type(crypt.decrypt)=='function'and type(crypt.hash)=='function','Fortuna: executor crypt.decrypt and crypt.hash required')
local decode=crypt.base64decode or(type(crypt.base64)=='table'and crypt.base64.decode)
assert(type(decode)=='function','Fortuna: base64 decoder unavailable')
local function digest(value)
    local hex=crypt.hash(value,'sha256')
    assert(type(hex)=='string'and #hex==64 and hex:match('^%x+$'),'Fortuna: invalid SHA-256 response')
    return hex:lower()
end
local function rawDigest(value)
    return(digest(value):gsub('%x%x',function(pair)return string.char(tonumber(pair,16))end))
end
local function mac(key,value)
    if #key>64 then key=rawDigest(key)end
    key=key..string.rep('\0',64-#key)
    local inner,outer={},{}
    for index=1,64 do
        local byte=key:byte(index)
        inner[index]=string.char(bit32.bxor(byte,0x36));outer[index]=string.char(bit32.bxor(byte,0x5c))
    end
    return digest(table.concat(outer)..rawDigest(table.concat(inner)..value))
end
local authenticated=PACKAGE.IV..'\n'..PACKAGE.SourceSHA256..'\n'..tostring(PACKAGE.SourceBytes)..'\n'..PACKAGE.Cipher
local actual=mac(decode(PACKAGE.MacKey),authenticated)
local difference=0
for index=1,64 do difference=bit32.bor(difference,bit32.bxor(actual:byte(index),PACKAGE.Tag:byte(index)or 0))end
assert(#PACKAGE.Tag==64 and difference==0,'Fortuna: encrypted payload integrity check failed')
local ok,plain=pcall(crypt.decrypt,PACKAGE.Cipher,PACKAGE.Key,PACKAGE.IV,'CBC')
assert(ok and type(plain)=='string','Fortuna: AES decryption failed')
assert(#plain==PACKAGE.SourceBytes and digest(plain)==PACKAGE.SourceSHA256,'Fortuna: decrypted build identity mismatch')
local entry,compileError=loadstring(plain,'Fortuna encrypted release')
assert(entry,compileError)
return entry()
